Code Meaning <code>ENOENT</code>, <code>EACCES</code>, <code>EEXIST</code>, … Native Node errno codes, preserved as-is. <code>ERR_INVALID_JSON</code> <code>useReadJsonFile</code> / <code>useReadModuleJson</code> could not parse the file. <code>ERR_VALIDATION</code> Parsed JSON failed the optional Zod schema (<code>error.details</code> carries the issues). <code>ERR_FS_UNAVAILABLE</code> The runtime is not Node/Bun (browser, edge). <code>useFileExists</code> returns <code>false</code>. <pre><code>const result = await useReadJsonFile("data/books.json", BooksSchema);

if (!result.ok) {
  console.error(result.error.code, result.error.path); // "ENOENT", "data/books.json"
}
</code></pre>

ReactSolidSvelteAngular <pre><code>import { useQuery, useSafeQueryFn } from "katanakit-js/adapters/react";
import { useGetApi, useInitApis } from "katanakit-js";

useInitApis({
  pokeapi: {
    baseUri: "https://pokeapi.co/api/v2",
    endpoints: { pokemonById: "/pokemon/:id/" },
  },
});

function Pokemon({ id }: { id: number }) {
  const { data, isPending, error } = useQuery({
    queryKey: ["pokemon", id],
    queryFn: useSafeQueryFn(() =&gt; useGetApi("pokeapi", "pokemonById", { params: { id } })),
  });

  if (isPending) return &lt;div&gt;Loading…&lt;/div&gt;;
  if (error) return &lt;div&gt;{error.message}&lt;/div&gt;;
  return &lt;div&gt;{data?.name}&lt;/div&gt;;
}
</code></pre> <pre><code>import { Show } from "solid-js";
import { useQuery, useSafeQueryFn } from "katanakit-js/adapters/solid";
import { useGetApi } from "katanakit-js";

function Pokemon() {
  const query = useQuery(() =&gt; ({
    queryKey: ["pokemon", 25],
    queryFn: useSafeQueryFn(() =&gt; useGetApi("pokeapi", "pokemonById", { params: { id: 25 } })),
  }));

  return (
    &lt;Show when={!query.isPending} fallback={&lt;div&gt;Loading…&lt;/div&gt;}&gt;
      &lt;div&gt;{query.data?.name}&lt;/div&gt;
    &lt;/Show&gt;
  );
}
</code></pre> <pre><code>&lt;script lang="ts"&gt;
